export const returnLabels={none:'No request',requested:'Requested',approved:'Approved',rejected:'Rejected',returned:'Return received',refund_recorded:'Refund recorded externally'};
export function orderRows(orders){return orders.map(o=>({...o,payment_status:o.payment_status||o.paymentStatus,payment_method:o.payment_method||o.paymentMethod,created_at:typeof o.created_at==='number'?o.created_at:Date.parse(o.createdAt),customer:o.customer||{name:'Customer',phone:''},courier_name:o.courier_name||'',shipment_id:o.shipment_id||'',tracking_url:o.tracking_url||'',return_status:o.return_status||'none',return_note:o.return_note||'',refund_amount_paise:o.refund_amount_paise||0,refund_reference:o.refund_reference||'',ops_revision:o.ops_revision||1}));}
export function filterOrders(orders,f){return orders.filter(o=>(!f.q||[o.ref,o.customer.name,o.customer.phone,...o.lines.map(l=>l.name)].join(' ').toLowerCase().includes(f.q.toLowerCase()))&&(!f.status||o.status===f.status)&&(!f.payment||o.payment_status===f.payment)&&(!f.method||o.payment_method===f.method)&&(!f.returns||o.return_status===f.returns)&&(!f.from||o.created_at>=Date.parse(f.from+'T00:00:00+05:30'))&&(!f.to||o.created_at<Date.parse(f.to+'T00:00:00+05:30')+86400000));}
export function orderReport(orders){const paid=orders.filter(o=>o.payment_status==='captured');return {orders:orders.length,paidOrders:paid.length,collectedPaise:paid.reduce((s,o)=>s+o.totalPaise,0),deliveryPaise:paid.reduce((s,o)=>s+(o.shipping_paise??o.feePaise??0),0),units:paid.reduce((s,o)=>s+o.lines.reduce((n,l)=>n+l.qty,0),0),recordedRefundPaise:orders.reduce((s,o)=>s+(o.refund_amount_paise||0),0)};}
export function csvCell(value){let s=String(value??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
export function ordersCSV(orders){return '\uFEFF'+[['Order','Created (UTC)','Mode','Customer','Phone','Status','Payment status','Payment method','Total INR','Delivery INR','Items','Courier','AWB','Tracking URL','Return status','Recorded refund INR','Refund reference'],...orders.map(o=>[o.ref,new Date(o.created_at).toISOString(),o.mode,o.customer.name,o.customer.phone,o.status,o.payment_status,o.payment_method,(o.totalPaise/100).toFixed(2),((o.shipping_paise??o.feePaise??0)/100).toFixed(2),o.lines.map(l=>l.name+' × '+l.qty).join('; '),o.courier_name,o.shipment_id,o.tracking_url,o.return_status,(o.refund_amount_paise/100).toFixed(2),o.refund_reference])].map(r=>r.map(csvCell).join(',')).join('\r\n');}
export function inventoryCSV(products){return '\uFEFF'+[['Product','Brand','Size ml','Format','Price INR','Total stock','Reserved','Free stock','Visibility'],...products.map(p=>[p.name,p.brand,p.size,p.format,p.price,p.quantity,p.held||0,p.quantity-(p.held||0),p.archived?'Archived':p.hidden?'Hidden':p.enquiryOnly?'Enquiry only':p.available?'Available':'Sold out'])].map(r=>r.map(csvCell).join(',')).join('\r\n');}
export function downloadCSV(csv,name){const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
